use std::fs;
use std::path::PathBuf;

use clap::Parser;
use serde::Deserialize;

use lib_cv::Point;
use lib_cv::modules::calibration::{CalibrationPointPair, CalibrationSolveConfig, CalibrationView, LensModel, solve_camera_intrinsics};

#[derive(Parser, Debug)]
struct Args {
    /// Path to a JSON file containing views/points (generated by a helper script).
    input: PathBuf,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct FileFormat {
    #[allow(dead_code)]
    lens_model: Option<String>,
    views: Vec<ViewEntry>,
}

#[derive(Debug, Deserialize)]
struct ViewEntry {
    // Present in the input format but not used by the solver.
    #[allow(dead_code)]
    image: String,
    points: Vec<PointPairEntry>,
}

#[derive(Debug, Deserialize)]
struct PointPairEntry {
    object: XY,
    image: XY,
}

#[derive(Debug, Deserialize)]
struct XY {
    x: f64,
    y: f64,
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();
    let data = fs::read_to_string(&args.input)?;
    let parsed: FileFormat = serde_json::from_str(&data)?;

    let mut views: Vec<CalibrationView> = Vec::with_capacity(parsed.views.len());
    for v in parsed.views {
        let mut points = Vec::with_capacity(v.points.len());
        for p in v.points {
            points.push(CalibrationPointPair::new(Point { x: p.object.x, y: p.object.y }, Point { x: p.image.x, y: p.image.y }));
        }
        views.push(CalibrationView::new(points));
    }

    let cfg = CalibrationSolveConfig { min_views: 2, min_points_per_view: 12, refine_distortion: true, undistort_iters: 5, refine_undistort_iters: 8, lens_model: LensModel::Fisheye };

    let res = solve_camera_intrinsics(&views, cfg).map_err(|e| anyhow::anyhow!("{e:?}"))?;
    eprintln!("views_used={} points_used={} reproj_rms_px={:.4}", res.views_used, res.points_used, res.reprojection_error_px);
    eprintln!("K fx={:.3} fy={:.3} cx={:.3} cy={:.3}", res.calibration.intrinsics.fx, res.calibration.intrinsics.fy, res.calibration.intrinsics.cx, res.calibration.intrinsics.cy);
    eprintln!("D k1={:.6} k2={:.6} k3={:.6} k4(p1)={:.6}", res.calibration.distortion.k1, res.calibration.distortion.k2, res.calibration.distortion.k3, res.calibration.distortion.p1);
    if !res.warnings.is_empty() {
        eprintln!("warnings:");
        for w in &res.warnings {
            eprintln!("- {w}");
        }
    }
    Ok(())
}
